import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react"
import { AnimatePresence, motion } from "framer-motion"
import {
  Library,
  Loader2,
  Menu,
  Radio,
  Settings,
  Wifi,
  WifiOff,
  X,
  type LucideIcon,
} from "lucide-react"

import HomePage from "./pages/HomePage"
import BroadcastPage from "./pages/BroadcastPage"
import SettingsPage from "./pages/SettingsPage"

type PageKey = "assets" | "broadcast" | "settings"
type BackendStatus = "checking" | "online" | "offline"

type SystemContextValue = {
  status: BackendStatus
  isOnline: boolean
  lastChecked: Date | null
  error: string | null
  refresh: () => Promise<void>
}

type NavItem = {
  key: PageKey
  label: string
  description: string
  icon: LucideIcon
}

const navItems: NavItem[] = [
  {
    key: "assets",
    label: "素材",
    description: "素材库与资源管理",
    icon: Library,
  },
  {
    key: "broadcast",
    label: "开播",
    description: "直播控制与推流状态",
    icon: Radio,
  },
  {
    key: "settings",
    label: "设置",
    description: "系统参数与偏好配置",
    icon: Settings,
  },
]

export const SystemContext = createContext<SystemContextValue | null>(null)

export function useSystem() {
  const context = useContext(SystemContext)

  if (!context) {
    throw new Error("useSystem must be used within SystemContext.Provider")
  }

  return context
}

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ")
}

function usePolling(intervalMs = 8000): SystemContextValue {
  const [status, setStatus] = useState<BackendStatus>("checking")
  const [lastChecked, setLastChecked] = useState<Date | null>(null)
  const [error, setError] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    const controller = new AbortController()
    const timeoutId = window.setTimeout(() => controller.abort(), 5000)

    try {
      const response = await fetch("/api/health", {
        method: "GET",
        cache: "no-store",
        signal: controller.signal,
      })

      if (!response.ok) {
        throw new Error(`后端状态异常：${response.status}`)
      }

      setStatus("online")
      setError(null)
    } catch (err) {
      setStatus("offline")
      setError(err instanceof Error ? err.message : "无法连接后端服务")
    } finally {
      window.clearTimeout(timeoutId)
      setLastChecked(new Date())
    }
  }, [])

  useEffect(() => {
    void refresh()

    const intervalId = window.setInterval(() => {
      void refresh()
    }, intervalMs)

    return () => {
      window.clearInterval(intervalId)
    }
  }, [intervalMs, refresh])

  return useMemo(
    () => ({
      status,
      isOnline: status === "online",
      lastChecked,
      error,
      refresh,
    }),
    [error, lastChecked, refresh, status],
  )
}

function AppLogo() {
  return (
    <div className="flex items-center gap-3">
      <div className="grid size-11 shrink-0 place-items-center rounded-2xl border border-border-strong bg-bg-deep text-accent shadow-gold">
        <svg
          aria-hidden="true"
          className="size-7"
          viewBox="0 0 32 32"
          fill="none"
        >
          <path
            d="M8.5 19.4V9.8C8.5 8.25 10.18 7.28 11.52 8.06L23.64 15.14C24.96 15.91 24.96 17.82 23.64 18.59L11.52 25.67C10.18 26.45 8.5 25.48 8.5 23.93V19.4Z"
            stroke="currentColor"
            strokeWidth="2.2"
            strokeLinejoin="round"
          />
          <path
            d="M18.5 10.5L23.8 7.8C25.13 7.12 26.7 8.08 26.7 9.58V24.42C26.7 25.92 25.13 26.88 23.8 26.2L18.5 23.5"
            stroke="currentColor"
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
            opacity="0.72"
          />
        </svg>
      </div>

      <div className="min-w-0">
        <p className="truncate text-sm font-semibold tracking-[0.28em] text-text-muted">
          LIVE STUDIO
        </p>
        <div className="flex items-center gap-2">
          <h1 className="truncate text-xl font-bold text-text-primary">
            AI Broadcast
          </h1>
          <span className="rounded-full border border-border bg-bg-raised px-2 py-0.5 text-xs font-semibold text-accent">
            v1.5
          </span>
        </div>
      </div>
    </div>
  )
}

function SystemStatusIndicator() {
  const { status, lastChecked, error, refresh } = useSystem()

  const statusLabel =
    status === "online"
      ? "后端已连接"
      : status === "offline"
        ? "后端离线"
        : "正在检查"

  const lastCheckedLabel = lastChecked
    ? new Intl.DateTimeFormat("zh-CN", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      }).format(lastChecked)
    : "尚未检查"

  const Icon =
    status === "online" ? Wifi : status === "offline" ? WifiOff : Loader2

  return (
    <section className="rounded-panel border border-border bg-bg-raised/80 p-4 shadow-soft backdrop-blur-xl">
      <div className="flex items-start gap-3">
        <div
          className={cn(
            "mt-1 grid size-9 shrink-0 place-items-center rounded-full border",
            status === "online" &&
              "border-success/50 bg-success/10 text-success",
            status === "offline" &&
              "border-danger/50 bg-danger/10 text-danger",
            status === "checking" &&
              "border-warning/50 bg-warning/10 text-warning",
          )}
        >
          <Icon
            aria-hidden="true"
            className={cn("size-4", status === "checking" && "animate-spin")}
          />
        </div>

        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold text-text-primary">
            {statusLabel}
          </p>
          <p className="mt-1 text-xs leading-5 text-text-muted">
            最近检查：{lastCheckedLabel}
          </p>
          {error ? (
            <p className="mt-2 line-clamp-2 text-xs leading-5 text-danger">
              {error}
            </p>
          ) : null}
        </div>
      </div>

      <button
        type="button"
        onClick={() => void refresh()}
        className="mt-4 w-full rounded-xl border border-border bg-bg-deep px-3 py-2 text-xs font-semibold text-text-body transition-colors hover:border-border-strong hover:text-accent"
      >
        重新检查连接
      </button>
    </section>
  )
}

function Navigation({
  activePage,
  onSelectPage,
}: {
  activePage: PageKey
  onSelectPage: (page: PageKey) => void
}) {
  return (
    <nav className="flex flex-col gap-2" aria-label="主导航">
      {navItems.map((item) => {
        const Icon = item.icon
        const isActive = activePage === item.key

        return (
          <button
            key={item.key}
            type="button"
            aria-current={isActive ? "page" : undefined}
            onClick={() => onSelectPage(item.key)}
            className={cn(
              "group flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left transition-all",
              isActive
                ? "border-border-strong bg-accent text-bg-deep shadow-gold"
                : "border-transparent text-text-muted hover:border-border hover:bg-bg-raised hover:text-text-primary",
            )}
          >
            <span
              className={cn(
                "grid size-10 shrink-0 place-items-center rounded-xl border transition-colors",
                isActive
                  ? "border-bg-deep/20 bg-bg-deep/10"
                  : "border-border bg-bg-deep text-accent group-hover:border-border-strong",
              )}
            >
              <Icon aria-hidden="true" className="size-5" />
            </span>

            <span className="min-w-0">
              <span className="block text-sm font-bold">{item.label}</span>
              <span
                className={cn(
                  "mt-0.5 block truncate text-xs",
                  isActive ? "text-bg-deep/70" : "text-text-muted",
                )}
              >
                {item.description}
              </span>
            </span>
          </button>
        )
      })}
    </nav>
  )
}

function Sidebar({
  activePage,
  onSelectPage,
  footer,
}: {
  activePage: PageKey
  onSelectPage: (page: PageKey) => void
  footer?: ReactNode
}) {
  return (
    <div className="flex h-full flex-col gap-8">
      <AppLogo />

      <Navigation activePage={activePage} onSelectPage={onSelectPage} />

      <div className="mt-auto">{footer}</div>
    </div>
  )
}

function PageContent({ activePage }: { activePage: PageKey }) {
  return (
    <AnimatePresence mode="wait" initial={false}>
      <motion.div
        key={activePage}
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -12 }}
        transition={{ duration: 0.22, ease: "easeOut" }}
        className="min-h-[calc(100vh-7rem)]"
      >
        {activePage === "assets" ? (
          <HomePage />
        ) : activePage === "broadcast" ? (
          <BroadcastPage />
        ) : (
          <SettingsPage />
        )}
      </motion.div>
    </AnimatePresence>
  )
}

export default function App() {
  const system = usePolling()
  const [activePage, setActivePage] = useState<PageKey>("assets")
  const [isSidebarOpen, setIsSidebarOpen] = useState(false)

  const activeItem = navItems.find((item) => item.key === activePage)

  const handleSelectPage = (page: PageKey) => {
    setActivePage(page)
    setIsSidebarOpen(false)
  }

  return (
    <SystemContext.Provider value={system}>
      <a href="#main-content" className="skip-to-content">
        跳到主要内容
      </a>

      <div className="min-h-screen text-text-body">
        <aside className="fixed inset-y-0 left-0 z-40 hidden w-72 border-r border-border bg-bg-page/90 p-5 shadow-soft backdrop-blur-xl lg:block">
          <Sidebar
            activePage={activePage}
            onSelectPage={handleSelectPage}
            footer={<SystemStatusIndicator />}
          />
        </aside>

        <AnimatePresence>
          {isSidebarOpen ? (
            <>
              <motion.button
                type="button"
                aria-label="关闭导航菜单"
                className="fixed inset-0 z-40 bg-bg-deep/70 backdrop-blur-sm lg:hidden"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                onClick={() => setIsSidebarOpen(false)}
              />

              <motion.aside
                className="fixed inset-y-0 left-0 z-50 w-80 max-w-[86vw] border-r border-border bg-bg-page p-5 shadow-soft lg:hidden"
                initial={{ x: "-100%" }}
                animate={{ x: 0 }}
                exit={{ x: "-100%" }}
                transition={{ duration: 0.24, ease: "easeOut" }}
              >
                <Sidebar
                  activePage={activePage}
                  onSelectPage={handleSelectPage}
                  footer={<SystemStatusIndicator />}
                />
              </motion.aside>
            </>
          ) : null}
        </AnimatePresence>

        <div className="lg:pl-72">
          <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-border bg-bg-page/82 px-4 backdrop-blur-xl lg:hidden">
            <button
              type="button"
              aria-label="打开导航菜单"
              aria-expanded={isSidebarOpen}
              onClick={() => setIsSidebarOpen(true)}
              className="grid size-10 place-items-center rounded-xl border border-border bg-bg-raised text-text-primary transition-colors hover:border-border-strong hover:text-accent"
            >
              {isSidebarOpen ? (
                <X aria-hidden="true" className="size-5" />
              ) : (
                <Menu aria-hidden="true" className="size-5" />
              )}
            </button>

            <div className="min-w-0 text-center">
              <p className="text-xs font-semibold tracking-[0.22em] text-text-muted">
                当前页面
              </p>
              <p className="truncate text-sm font-bold text-text-primary">
                {activeItem?.label ?? "素材"}
              </p>
            </div>

            <div
              className={cn(
                "size-2.5 rounded-full",
                system.status === "online" && "bg-success",
                system.status === "offline" && "bg-danger",
                system.status === "checking" && "bg-warning",
              )}
              aria-label={
                system.status === "online"
                  ? "后端已连接"
                  : system.status === "offline"
                    ? "后端离线"
                    : "正在检查后端状态"
              }
            />
          </header>

          <main
            id="main-content"
            className="mx-auto w-full max-w-7xl px-4 py-6 sm:px-6 lg:px-8 lg:py-8"
          >
            <div className="mb-6 hidden items-center justify-between gap-6 lg:flex">
              <div>
                <p className="text-sm font-semibold tracking-[0.28em] text-text-muted">
                  CONTROL PANEL
                </p>
                <h2 className="mt-2 text-3xl font-bold text-text-primary">
                  {activeItem?.label ?? "素材"}
                </h2>
              </div>

              <div className="rounded-full border border-border bg-bg-raised px-4 py-2 text-sm text-text-muted shadow-soft">
                <span className="text-text-body">版本</span>
                <span className="ml-2 font-bold text-accent">v1.5</span>
              </div>
            </div>

            <PageContent activePage={activePage} />
          </main>
        </div>
      </div>
    </SystemContext.Provider>
  )
}
